package com.smartmanager.nativeapp; import android.content.*;import android.graphics.*;import android.graphics.pdf.PdfDocument;import android.net.Uri;import java.io.*;import java.util.*;
public final class PdfService{private PdfService(){}public static void write(Context c,Uri d,ArrayList<String[]> a)throws Exception{write(c,d,a,new TemplateStore(c).get());}public static void write(Context c,Uri d,ArrayList<String[]>a,CardTemplate t)throws Exception{PdfDocument z=new PdfDocument();Bitmap bg=null;try{if(!t.imageUri.isEmpty())try(InputStream in=c.getContentResolver().openInputStream(Uri.parse(t.imageUri))){bg=BitmapFactory.decodeStream(in);}int i=0,n=1;float w=(t.paperW-2*t.margin-(t.columns-1)*t.gap)/(float)t.columns,h=(t.paperH-2*t.margin-(t.rows-1)*t.gap)/(float)t.rows;while(i<a.size()){PdfDocument.Page p=z.startPage(new PdfDocument.PageInfo.Builder(t.paperW,t.paperH,n++).create());for(int k=0;k<t.perPage()&&i<a.size();k++,i++)drawCard(p.getCanvas(),a.get(i),t,bg,t.margin+(k%t.columns)*(w+t.gap),t.margin+(k/t.columns)*(h+t.gap),w,h);z.finishPage(p);}try(OutputStream o=c.getContentResolver().openOutputStream(d)){if(o==null)throw new IOException("Cannot open output file");z.writeTo(o);}}finally{if(bg!=null&&!bg.isRecycled())bg.recycle();z.close();}}public static void drawCard(Canvas c,String[]a,CardTemplate t,Bitmap bg,float x,float y,float w,float h){Paint p=new Paint(3);p.setColor(Color.WHITE);c.drawRoundRect(x,y,x+w,y+h,10,10,p);if(bg!=null)c.drawBitmap(bg,null,new RectF(x,y,x+w,y+h),p);p.setColor(Color.rgb(15,65,105));float q=y+24;if(t.showUser){p.setTextSize(t.userSize);c.drawText(a.length>0?a[0]:"",x+12,q,p);q+=t.userSize+4;}if(t.showPassword){p.setTextSize(t.passwordSize);c.drawText(a.length>1?"Pass: "+a[1]:"",x+12,q,p);q+=t.passwordSize+4;}if(t.showProfile){p.setTextSize(t.profileSize);c.drawText(a.length>2?"Profile: "+a[2]:"",x+12,q,p);}}

}